				if (((List<Hero>)(object)Clan.PlayerClan.Companions).Count >= Clan.PlayerClan.CompanionLimit)
				{
					flag = (PreconditionFlags)((uint)flag | 0x10000u);
				}
				return (int)flag == 0;
