			if (ConditionsHold(hero))
			{
				Campaign.Current.IssueManager.AddPotentialIssueData(hero, new PotentialIssueData(new StartIssueDelegate(OnStartIssue), typeof(SnareTheWealthyIssue), (IssueFrequency)2, (object)null));
