		}

		private bool CheckIfTheMainAgentIsBeingEscorted()
		{
			foreach (Agent item in (List<Agent>)(object)Mission.Current.Agents)
			{
				if (EscortAgentBehavior.CheckIfAgentIsEscortedBy(item, Agent.Main))
