			if (((oneToOneConversationAgent != null) ? oneToOneConversationAgent.GetComponent<CampaignAgentComponent>().AgentNavigator : null) != null)
			{
				EscortAgentBehavior.RemoveEscortBehaviorOfAgent(oneToOneConversationAgent);
			}
		}

