				Separator();
				ImGUITextArea("Character Relation With Main Hero:", separatorNeeded: false, onSameLine: false);
				ImGUITextArea("Leave -1 for no change, 0 for enemy, 1 for neutral, 2 for friend", separatorNeeded: false, onSameLine: false);
