		private bool CanPlayerStartPrisonBreak(Settlement settlement)
		{
			bool flag = true;
			if (_coolDownData.TryGetValue(settlement, out var value))
			{
				flag = ((CampaignTime)(ref value)).IsPast;
				if (flag)
				{
					_coolDownData.Remove(settlement);
				}
			}
			return flag;
		}

