					}
					if (MovesLeftToEndTurn == 0)
					{
						EndTurn();
					}
					else
					{
						UpdateTurn(dt);
					}
					CheckSwitchPlayerTurn();
					return true;
				}
				return false;
			}
			return false;
		}

