			{
				PlayerTurn = PlayerTurn.PlayerOneWaiting;
			}
			else if (PlayerTurn == PlayerTurn.PlayerTwo)
			{
				PlayerTurn = PlayerTurn.PlayerTwoWaiting;
			}
			JustStoppedDraggingUnit = false;
		}

