			}
			IEnumerable<GameEntity> source = from x in BoardEntity.GetChildren()
				where x.Tags.Any((string t) => t.Contains("tile_"))
				select x;
			IEnumerable<GameEntity> source2 = from x in BoardEntity.GetChildren()
				where x.Tags.Any((string t) => t.Contains("decal_"))
				select x;
			int x2 = 0;
			while (x2 < TileCount)
			{
				GameEntity val = source.Single((GameEntity e) => e.HasTag("tile_" + x2));
				BoardGameDecal firstScriptOfType = source2.Single((GameEntity e) => e.HasTag("decal_" + x2)).GetFirstScriptOfType<BoardGameDecal>();
				int xLeft;
				int xRight;
				switch (x2)
				{
				case 0:
					xLeft = (xRight = -1);
					break;
				case 1:
					xLeft = 8;
					xRight = 2;
					break;
				case 8:
					xLeft = 7;
					xRight = 1;
					break;
				default:
					xLeft = x2 - 1;
					xRight = x2 + 1;
					break;
				}
				base.Tiles[x2] = new TileMuTorere(val, firstScriptOfType, x2, xLeft, xRight);
				GameEntityPhysicsExtensions.CreateVariableRatePhysics(val, true);
				int num = x2 + 1;
				x2 = num;
