				OnExitSeparateThread(calculatedMove);
			}
		}

		private bool OnBeginSeparateThread()
		{
			bool flag = false;
			lock (_stateLock)
			{
				if (AbortRequested)
				{
					_state = AIState.Aborted;
					flag = true;
				}
				else
				{
					_state = AIState.Running;
				}
			}
			return !flag;
		}

		private void OnExitSeparateThread(Move calculatedMove)
		{
			lock (_stateLock)
			{
